mapper.select:
SELECT COUNT(*)
FROM USER_REFRESH_TOKEN
WHERE USER_ID = #{userId}
AND JTI = #{jti}
AND REVOKED_YN = 'N'
AND EXPIRES_AT > SYSTIMESTAMP

mapper.update:
UPDATE USER_REFRESH_TOKEN
SET REVOKED_YN = 'Y',
REVOKED_AT = SYSTIMESTAMP
WHERE USER_ID = #{userId}
AND JTI = #{jti}
AND REVOKED_YN = 'N'
